begin
  select count(*) into n from platform.definer_client_grant_grandfather
   where (schema_name, function_name, identity_args) in (

     ('seo','dimension_matcher_delete','p_matcher_id uuid'),
     ('seo','dimension_matcher_upsert','p_site_id uuid, p_value_id uuid, p_kind text, p_pattern text, p_place_id uuid, p_fact_value_id uuid, p_condition_rule_id uuid, p_origin text, p_notes text, p_enabled boolean'),
     ('seo','facet_dimension_archive','p_dimension text, p_drop_facts boolean, p_site_id uuid'),
